<?php
/**
 * MCP resources of the knowledge layer: the guide, the attribute reference, the
 * per-module reference and the layout tree schema.
 *
 * The Markdown files live in knowledge/ (guide.md and attributes.md are written by
 * hand; modules/ is generated by tools/generate-catalog.php). The schema is the
 * one the layout tools validate against (includes/Divi/schema/layout.schema.json),
 * served as is so it can never drift from them.
 *
 * @package WPDM
 */

namespace WPDM\Knowledge;

use WPDM\Divi\LayoutTree;
use WPDM\Mcp\Registry;
use WPDM\Mcp\Resource;

defined( 'ABSPATH' ) || exit;

/**
 * Registers and reads the knowledge resources.
 */
final class Resources {

	const GUIDE      = 'divi://guide';
	const ATTRIBUTES = 'divi://attributes';
	const INDEX      = 'divi://modules/index';
	const MODULE     = 'divi://modules/{name}';
	const SCHEMA     = 'divi://schema/layout';

	const MARKDOWN = 'text/markdown';

	/**
	 * Module names accepted by the template (block name without "divi/").
	 */
	const MODULE_NAME = '/^[a-z0-9-]+$/';

	/**
	 * Add the resources to a registry.
	 *
	 * @param Registry $registry Registry.
	 * @return void
	 */
	public static function register( Registry $registry ): void {
		$registry->add_resource(
			new Resource(
				self::GUIDE,
				'Divi 5 page building guide',
				self::MARKDOWN,
				static function () {
					return self::file( 'guide.md' );
				},
				'Read first: how to build good Divi 5 pages with these tools (workflow, layout tree format, composition rules, complete examples, safety rules).'
			)
		);
		$registry->add_resource(
			new Resource(
				self::ATTRIBUTES,
				'Divi 5 attribute reference',
				self::MARKDOWN,
				static function () {
					return self::file( 'attributes.md' );
				},
				'Shape of Divi 5 block attributes: breakpoints and states, decoration groups (spacing, background, border, font...), globals, custom CSS, rows/columns, icons.'
			)
		);
		$registry->add_resource(
			new Resource(
				self::INDEX,
				'Divi 5 module index',
				self::MARKDOWN,
				static function () {
					return self::file( 'modules/INDEX.md' );
				},
				'Every Divi 5 module of the installed version with its title, category and children; read divi://modules/{name} for one module.'
			)
		);
		$registry->add_resource_template(
			self::MODULE,
			'Divi 5 module reference',
			self::MARKDOWN,
			array( self::class, 'module' )
		);
		$registry->add_resource(
			new Resource(
				self::SCHEMA,
				'Layout tree JSON Schema',
				'application/json',
				static function () {
					return self::read( LayoutTree::SCHEMA_FILE );
				},
				'JSON Schema of the layout tree accepted by divi_build_layout, divi_validate_layout, divi_apply_layout and divi_create_page.'
			)
		);
	}

	/**
	 * Template reader: one module's reference, null for an unknown or invalid name.
	 *
	 * @param array $vars {name}: block name without "divi/", e.g. "group".
	 * @return string|null
	 */
	public static function module( array $vars ) {
		$name = isset( $vars['name'] ) && is_string( $vars['name'] ) ? $vars['name'] : '';
		if ( ! preg_match( self::MODULE_NAME, $name ) ) {
			return null;
		}
		$path = self::dir() . 'modules/' . $name . '.md';
		return is_file( $path ) ? self::read( $path ) : null;
	}

	/**
	 * The knowledge folder.
	 *
	 * @return string
	 */
	public static function dir(): string {
		return WPDM_DIR . 'knowledge/';
	}

	/**
	 * A file of the knowledge folder.
	 *
	 * @param string $relative Path below knowledge/.
	 * @return string
	 */
	private static function file( string $relative ): string {
		return self::read( self::dir() . $relative );
	}

	/**
	 * @param string $path File.
	 * @return string
	 * @throws \RuntimeException When the file cannot be read (a broken install).
	 */
	private static function read( string $path ): string {
		$text = is_readable( $path ) ? file_get_contents( $path ) : false; // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
		if ( false === $text ) {
			throw new \RuntimeException( 'Knowledge file missing: ' . basename( $path ) );
		}
		return $text;
	}

	private function __construct() {}
}
